     <script>
       const faqs = [
         {
           question: "Why do cats purr?",
           answer:
             "Cats often purr when they are relaxed, but they may also purr while asking for attention, coping with stress, or recovering from discomfort. It is a flexible form of communication, not just a sign of happiness.",
         },
         {
           question: "Do cats need baths?",
           answer:
