           question: "How much sleep do cats need?",
           answer:
             "Cats are natural nappers and may sleep 12 to 16 hours a day, sometimes more. Short bursts of activity between naps are normal, especially around dawn and dusk.",
         },
         {
           question: "Why do cats stare at people?",
           answer:
             "A cat may be curious, waiting for food, reading your body language, or simply watching the room. Slow blinking back can help communicate that you are calm and friendly.",
         },
         {
           question: "What makes a cat happy indoors?",
           answer: "A good indoor cat setup usually includes:",
           list: [
             "Daily play that mimics hunting",
             "Scratching posts and climbing spaces",
             "Clean litter boxes in quiet locations",
             "Fresh water, regular feeding, and predictable routines",
           ],
         },
       ];

       function el(tag, attrs = {}, ...children) {
         const node = document.createElement(tag);
         for (const [key, value] of Object.entries(attrs)) {
           if (value == null) continue;
           if (key === "className") {
             node.setAttribute("class", value);
           } else if (key === "dataset") {
             Object.assign(node.dataset, value);
           } else if (key === "hidden") {
             node.hidden = value;
           } else if (key === "text") {
             node.textContent = value;
           } else if (key.startsWith("aria-") || key === "role" || key === "id" || key === "type") {
             node.setAttribute(key, value);
           } else if (key in node) {
             node[key] = value;
           } else {
             node.setAttribute(key, value);
           }
         }
         for (const child of children.flat()) {
           if (child == null) continue;
           node.append(child.nodeType ? child : document.createTextNode(String(child)));
         }
         return node;
       }

       function Chevron() {
         return el(
           "svg",
           {
             className: "chevron",
             viewBox: "0 0 24 24",
             "aria-hidden": "true",
             fill: "none",
           },
           el("path", {
             d: "M6 9l6 6 6-6",
             stroke: "currentColor",
             "stroke-width": "2",
             "stroke-linecap": "round",
             "stroke-linejoin": "round",
