             "aria-expanded": "false",
             "aria-controls": `${id}-panel`,
           },
           el("span", { text: item.question }),
           Chevron()
         );

         const answerNodes = [el("p", { text: item.answer })];
         if (item.list) {
           answerNodes.push(
             el(
               "ul",
               {},
               ...item.list.map((line) => el("li", { text: line }))
             )
           );
         }

         const panel = el("div", {
           className: "details",
           id: `${id}-panel`,
           hidden: true,
         }, answerNodes);

         button.addEventListener("click", () => {
           const expanded = button.getAttribute("aria-expanded") === "true";
           button.setAttribute("aria-expanded", String(!expanded));
           panel.hidden = expanded;
         });

         return el("div", { className: "example" }, button, panel);
